compose:
name: ${CONTAINER_PREFIX:-grafana-observability}
x-default-logging:
  driver: json-file
  options:
    max-size: ${DOCKER_LOG_MAX_SIZE:-10m}
    max-file: ${DOCKER_LOG_MAX_FILE:-3}
services:
  grafana:
    image: grafana/grafana:${GRAFANA_VERSION:-13.0.1}
    restart: unless-stopped
    depends_on:
      loki:
        condition: service_started
    environment:
    - GF_SECURITY_ADMIN_USER=${GRAFANA_ADMIN_USER:?set GRAFANA_ADMIN_USER}
    - GF_SECURITY_ADMIN_PASSWORD=${GRAFANA_ADMIN_PASSWORD:?set GRAFANA_ADMIN_PASSWORD}
    - GF_SERVER_ROOT_URL=${GRAFANA_ROOT_URL:?set GRAFANA_ROOT_URL}
    - GF_SECURITY_COOKIE_SECURE=${GRAFANA_COOKIE_SECURE:-true}
    - GF_SECURITY_COOKIE_SAMESITE=${GRAFANA_COOKIE_SAMESITE:-lax}
    - GF_SECURITY_CONTENT_SECURITY_POLICY=${GRAFANA_CONTENT_SECURITY_POLICY:-true}
    - GF_AUTH_ANONYMOUS_ENABLED=false
    - GF_AUTH_ANONYMOUS_HIDE_VERSION=true
    - GF_USERS_ALLOW_SIGN_UP=false
    - GF_USERS_ALLOW_ORG_CREATE=false
    - GF_SNAPSHOTS_EXTERNAL_ENABLED=false
    - GF_METRICS_ENABLED=false
    - GF_ANALYTICS_REPORTING_ENABLED=false
    - GF_ANALYTICS_CHECK_FOR_UPDATES=false
    - GF_SECURITY_DISABLE_GRAVATAR=true
    - GF_LOG_MODE=console
    - GF_LOG_LEVEL=${GRAFANA_LOG_LEVEL:-info}
    - GF_PATHS_PROVISIONING=/etc/grafana/provisioning
    expose:
    - '3000'
    volumes:
    - grafana-data:/var/lib/grafana
    - ../files/config/grafana/provisioning:/etc/grafana/provisioning:ro
    - ../files/config/grafana/dashboards:/var/lib/grafana/dashboards:ro
    healthcheck:
      test:
      - CMD-SHELL
      - wget -qO- http://127.0.0.1:3000/api/health >/dev/null || exit 1
      interval: ${GRAFANA_HEALTH_INTERVAL:-30s}
      timeout: ${GRAFANA_HEALTH_TIMEOUT:-5s}
      retries: ${GRAFANA_HEALTH_RETRIES:-5}
      start_period: ${GRAFANA_HEALTH_START_PERIOD:-45s}
    stop_grace_period: ${GRAFANA_STOP_GRACE_PERIOD:-30s}
    logging:
      driver: json-file
      options:
        max-size: ${DOCKER_LOG_MAX_SIZE:-10m}
        max-file: ${DOCKER_LOG_MAX_FILE:-3}
    networks:
    - observability
  loki:
    image: grafana/loki:${LOKI_VERSION:-3.7.0}
    restart: unless-stopped
    command:
    - -config.file=/etc/loki/loki-config.yaml
    - -config.expand-env=true
    environment:
    - LOKI_LOG_LEVEL=${LOKI_LOG_LEVEL:-info}
    - LOKI_S3_BUCKET=${LOKI_S3_BUCKET:?set LOKI_S3_BUCKET}
    - LOKI_S3_ENDPOINT=http://minio:9000
    - LOKI_S3_REGION=${LOKI_S3_REGION:?set LOKI_S3_REGION}
    - LOKI_S3_ACCESS_KEY_ID=${MINIO_ROOT_USER:?set MINIO_ROOT_USER}
    - LOKI_S3_SECRET_ACCESS_KEY=${MINIO_ROOT_PASSWORD:?set MINIO_ROOT_PASSWORD}
    - LOKI_S3_FORCE_PATH_STYLE=true
    - LOKI_S3_INSECURE=true
    - LOKI_RETENTION_PERIOD=${LOKI_RETENTION_PERIOD:-720h}
    - LOKI_INGESTION_RATE_MB=${LOKI_INGESTION_RATE_MB:-16}
    - LOKI_INGESTION_BURST_SIZE_MB=${LOKI_INGESTION_BURST_SIZE_MB:-32}
    - LOKI_MAX_QUERY_SERIES=${LOKI_MAX_QUERY_SERIES:-5000}
    - LOKI_MAX_ENTRIES_LIMIT_PER_QUERY=${LOKI_MAX_ENTRIES_LIMIT_PER_QUERY:-5000}
    - LOKI_QUERY_TIMEOUT=${LOKI_QUERY_TIMEOUT:-2m}
    - LOKI_MAX_QUERY_LOOKBACK=${LOKI_MAX_QUERY_LOOKBACK:-720h}
    - LOKI_REJECT_OLD_SAMPLES_MAX_AGE=${LOKI_REJECT_OLD_SAMPLES_MAX_AGE:-168h}
    - LOKI_CHUNK_IDLE_PERIOD=${LOKI_CHUNK_IDLE_PERIOD:-30m}
    - LOKI_MAX_CHUNK_AGE=${LOKI_MAX_CHUNK_AGE:-2h}
    - LOKI_CHUNK_TARGET_SIZE=${LOKI_CHUNK_TARGET_SIZE:-1572864}
    - LOKI_TSDB_CACHE_TTL=${LOKI_TSDB_CACHE_TTL:-24h}
    - LOKI_COMPACTION_INTERVAL=${LOKI_COMPACTION_INTERVAL:-10m}
    - LOKI_RETENTION_DELETE_DELAY=${LOKI_RETENTION_DELETE_DELAY:-2h}
    - LOKI_RETENTION_DELETE_WORKER_COUNT=${LOKI_RETENTION_DELETE_WORKER_COUNT:-50}
    expose:
    - '3100'
    volumes:
    - ../files/config/loki/loki-config.yaml:/etc/loki/loki-config.yaml:ro
    - loki-data:/loki
    healthcheck:
      test:
      - CMD-SHELL
      - wget -qO- http://127.0.0.1:3100/ready >/dev/null || exit 1
      interval: ${LOKI_HEALTH_INTERVAL:-30s}
      timeout: ${LOKI_HEALTH_TIMEOUT:-5s}
      retries: ${LOKI_HEALTH_RETRIES:-5}
      start_period: ${LOKI_HEALTH_START_PERIOD:-45s}
    stop_grace_period: ${LOKI_STOP_GRACE_PERIOD:-2m}
    logging:
      driver: json-file
      options:
        max-size: ${DOCKER_LOG_MAX_SIZE:-10m}
        max-file: ${DOCKER_LOG_MAX_FILE:-3}
    networks:
    - observability
    depends_on:
      minio-createbucket:
        condition: service_completed_successfully
  minio:
    image: ghcr.io/coollabsio/minio:${MINIO_VERSION:-RELEASE.2025-10-15T17-29-55Z}
    restart: unless-stopped
    command: server --console-address ":9001" /data
    environment:
    - MINIO_ROOT_USER=${MINIO_ROOT_USER:?set MINIO_ROOT_USER}
    - MINIO_ROOT_PASSWORD=${MINIO_ROOT_PASSWORD:?set MINIO_ROOT_PASSWORD}
    expose:
    - '9000'
    - '9001'
    volumes:
    - minio-data:/data
    healthcheck:
      test:
      - CMD
      - mc
      - ready
      - local
      interval: ${MINIO_HEALTH_INTERVAL:-30s}
      timeout: ${MINIO_HEALTH_TIMEOUT:-10s}
      retries: ${MINIO_HEALTH_RETRIES:-5}
      start_period: ${MINIO_HEALTH_START_PERIOD:-30s}
    stop_grace_period: ${MINIO_STOP_GRACE_PERIOD:-30s}
    logging:
      driver: json-file
      options:
        max-size: ${DOCKER_LOG_MAX_SIZE:-10m}
        max-file: ${DOCKER_LOG_MAX_FILE:-3}
    networks:
    - observability
  minio-createbucket:
    image: ghcr.io/coollabsio/minio:${MINIO_VERSION:-RELEASE.2025-10-15T17-29-55Z}
    restart: 'no'
    depends_on:
      minio:
        condition: service_healthy
    environment:
    - MINIO_ROOT_USER=${MINIO_ROOT_USER:?set MINIO_ROOT_USER}
    - MINIO_ROOT_PASSWORD=${MINIO_ROOT_PASSWORD:?set MINIO_ROOT_PASSWORD}
    - LOKI_S3_BUCKET=${LOKI_S3_BUCKET:?set LOKI_S3_BUCKET}
    entrypoint:
    - /bin/sh
    - -c
    - 'mc alias set local http://minio:9000 "$$MINIO_ROOT_USER" "$$MINIO_ROOT_PASSWORD"

      mc mb --ignore-existing "local/$$LOKI_S3_BUCKET"

      '
    logging:
      driver: json-file
      options:
        max-size: ${DOCKER_LOG_MAX_SIZE:-10m}
        max-file: ${DOCKER_LOG_MAX_FILE:-3}
    networks:
    - observability
networks:
  observability:
    driver: bridge
volumes:
  grafana-data: null
  loki-data: null
  minio-data: null
